#include <cassert>
#include <chrono>
#include <iostream>

int main() {
    auto ymdl{11 / std::chrono::last / 2020};
    std::cout << ymdl << '\n';

    ymdl = std::chrono::years(10) + ymdl;
    std::cout << ymdl << '\n';
    assert(
        ymdl == std::chrono::day(30) / std::chrono::November / std::chrono::year(2030));

    ymdl = ymdl - std::chrono::months(6);
    std::cout << ymdl << '\n';
    assert(ymdl == std::chrono::day(31) / std::chrono::May / std::chrono::year(2030));
}
